use std::io::{self, Read, Write};

fn lower_bound(v: &[i64], x: i64) -> usize {
    let mut lo = 0usize;
    let mut hi = v.len();

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if v[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    lo
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_ascii_whitespace().map(|t| t.parse::<i64>().unwrap());

    let n = it.next().unwrap_or(0) as usize;
    let v: Vec<i64> = (0..n).map(|_| it.next().unwrap()).collect();
    let q = it.next().unwrap_or(0) as usize;

    let out = io::stdout();
    let mut out = io::BufWriter::new(out.lock());
    for _ in 0..q {
        let x = it.next().unwrap();
        writeln!(out, "{}", lower_bound(&v, x)).unwrap();
    }
}
